from collections import deque

def transform(grid):
    if not grid:
        return grid

    R = len(grid)
    C = len(grid[0]) if R > 0 else 0

    # Identify background color (most frequent, typically 3 here)
    counts = {}
    for r in range(R):
        for c in range(C):
            val = grid[r][c]
            counts[val] = counts.get(val, 0) + 1
    bg_color = max(counts, key=counts.get)
    fill_color = 4

    # Flood fill to find all background pixels connected to the boundary (outside)
    visited = [[False] * C for _ in range(R)]
    queue = deque()

    # Add boundary pixels to queue if they are background
    for c in range(C):
        if grid[0][c] == bg_color:
            visited[0][c] = True
            queue.append((0, c))
    for c in range(C):
        if grid[R-1][c] == bg_color:
            visited[R-1][c] = True
            queue.append((R-1, c))
    for r in range(R):
        if grid[r][0] == bg_color:
            visited[r][0] = True
            queue.append((r, 0))
    for r in range(R):
        if grid[r][C-1] == bg_color:
            visited[r][C-1] = True
            queue.append((r, C-1))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                if not visited[nr][nc] and grid[nr][nc] == bg_color:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Fill enclosed background pixels with 4
    for r in range(R):
        for c in range(C):
            if grid[r][c] == bg_color and not visited[r][c]:
                grid[r][c] = fill_color

    return grid
